// features: Vendor lifecycle, "A vendor that was sent back can be edited again"
import { expect, expectStatus, test, uniqueName } from "../../fixtures";

test("a vendor whose contract extraction was rejected can be renamed", { tag: "@LIF-09" }, async ({ factory, apiAs }) => {
  // Arrange
  const { vendor, documents, extractions } = await factory.vendorInReview({ as: "member" });
  const reviewer = await apiAs("reviewer");
  const decision = await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, {
    data: { decision: "reject", note: "Contract page is unreadable" },
  });
  await expectStatus(decision, 200);
  expect((await factory.extraction(documents.contract.id, "member")).status).toBe("rejected");

  const member = await apiAs("member");
  const newName = uniqueName("Renamed Vendor");

  // Act
  const response = await member.patch(`/api/vendors/${vendor.id}`, {
    data: { name: newName },
  });

  // Assert
  const updated = await expectStatus<{ id: string; name: string }>(response, 200);
  expect(updated.name).toBe(newName);

  const stored = await expectStatus<{ name: string }>(await member.get(`/api/vendors/${vendor.id}`), 200);
  expect(stored.name).toBe(newName);
});
